export type Guide = { id:string; title:string; category:string; description:string; read:number; source:string; sections:{title:string; paragraphs:string[]; bullets?:string[]}[] };
export const guides:Guide[] = [
{id:'elegir-oficio',title:'Cómo elegir tu primer oficio',category:'Inicio',description:'Una ruta de progresión para probar transporte, minería, industria y combate sin perder de vista tus gastos.',read:5,source:'Partida nueva · Contratos · Equipamiento · Enciclopedia · Síntesis de la wiki',sections:[
{title:'Prueba antes de especializarte',paragraphs:['Recomendación de la wiki: usa la Albor inicial para conocer los paneles y probar actividades pequeñas. Sus 3 SCU obligan a planificar la carga, pero permiten aprender el ciclo de entrega, las operaciones de mercado y el manejo del MSP Pico que trae la nave de cortesía.','La campaña de Kira introduce el juego y ofrece recompensas de bienvenida. No tomes el precio de una nave como el único objetivo de progreso: los materiales, la reputación, el equipo y la capacidad de volver a puerto también cuentan.']},
{title:'Transporte y comercio',paragraphs:['Si disfrutas preparando rutas, empieza leyendo contratos de entrega y comparando el espacio del paquete con tu bodega libre. El pago contractual y el margen de una mercancía comprada son dos balances diferentes.','Para comercio, calcula la venta total menos compra, combustible, reparaciones y, si utilizas una rutina de venta, la comisión. Las cotizaciones de esta wiki están fechadas; comprueba el mercado antes de cargar. Usa el comparador para estudiar una bodega mayor sin confundir capacidad con rentabilidad.']},
{title:'Minería e industria',paragraphs:['Si prefieres extraer y transformar, estudia los campos del atlas y los usos de cada mineral. Las fichas enlazan recursos con refinerías, estaciones y productos; las cantidades por hora de una fábrica de estación describen su economía, no un trabajo personal.','En fabricación, revisa aprendizaje, nivel, ingredientes y tarifa por separado. Recomendación de la wiki: planifica primero un lote pequeño y comprueba la cola. El calculador permite asignar tu propio coste a cada material; tenerlo en almacén no elimina su valor de oportunidad.']},
{title:'Combate y servicios',paragraphs:['Para combate, empieza entendiendo SCM, energía, escudos, alcance y selección de objetivo. La protección de novato frente a otros jugadores no te hace inmune a NPC. Los DPS de catálogo tampoco predicen por sí solos el resultado de un enfrentamiento.','El rescate, la reparación y las operaciones de flota requieren leer objetivos y condiciones. Recomendación de la wiki: reserva un margen para volver a puerto y consulta los seguros antes de montar equipo que no puedas reemplazar.']},
{title:'Mide una sesión completa',paragraphs:['Anota gasto inicial, venta o recompensa, consumibles, daños y duración desde la preparación hasta el regreso. Esa comparación ayuda a elegir una actividad acorde con tu equipo y con lo que te apetece hacer.','Las guías de comercio, minería, fabricación, combate y seguros amplían cada paso. Las fichas guardadas te permiten reunir tus materiales, cascos y componentes en un archivo personal del navegador.']}]},
{id:'primeros-pasos',title:'Tu primer día en Sol',category:'Inicio',description:'De la bahía de Meridian a tu primera entrega. Todo lo que conviene saber antes de despegar.',read:7,source:'Partida nueva · Equipamiento · Ayuda · Novedades 0.9.50 y 0.9.71',sections:[
{title:'El punto de partida',paragraphs:['Una partida nueva empieza atracada en Estación Meridian, en el espacio terrestre, con 5.000 CR, una MSP Albor Mk I y 3 SCU de bodega. La cuenta de investigación empezó con +10 de reputación con MSP (Conocido), 0 con HCA, FMU y Tharsis, y −10 con Nox (Sospechoso).','La Albor de cortesía tiene dos MSP Chispa: 286 DPS nominales combinados. Sus dos MSP Muro aportan 4.000 de escudo y la planta entrega 6 puntos de energía. La pantalla Equipamiento confirma un MSP Pico montado en la Albor inicial. La enciclopedia genérica del casco aún muestra el hueco de minería vacío: distingue el regalo inicial de la ficha de catálogo.']},
{title:'Conoce la estación',paragraphs:['Resumen muestra servicios, armisticio y naves locales. Mercado sirve para comprar y vender mercancías. Equipamiento muestra los huecos reales de tu nave; Astillero gestiona tus cascos. Fabricación enseña planos y trabajos, Contratos ofrece encargos y Servicios reúne reparación, combustible, rearme, hogar y seguros.','En Meridian el radio de armisticio observado es 5 km. Puedes abrir el mapa mientras estás atracado para estudiar destinos y rutinas; las órdenes que mueven la nave requieren despegar.']},
{title:'Una primera sesión razonable',paragraphs:['Recomendación de la wiki: sigue a Kira, prueba una entrega pequeña y guarda parte de tus créditos para combustible y reparación. Una entrega de 1 SCU deja 2 SCU libres en la Albor; una de 2,5 SCU deja solo 0,5. No compres carga antes de comprobar el volumen de los paquetes.'],bullets:['Lee el destino, el plazo y el riesgo antes de aceptar.','Comprueba la reputación necesaria para atracar y comerciar.','Usa Ir y verifica las paradas que propone el mapa.','Revisa tu póliza antes de llevar mejoras valiosas.','Vuelve a Servicios al atracar para reparar y repostar.']},
{title:'Qué ocurre si pierdes la nave',paragraphs:['La Albor inicial aparece sin seguro. La pantalla Servicios ofrecía Básica por 5.700 CR y Completa por 6.600 CR, ambas por encima del saldo inicial. Una nave destruida sin póliza se pierde con lo que lleve. En tu hogar siempre queda disponible una Albor de cortesía gratis.','La destrucción y la inutilización son estados distintos. Una nave sin casco puede quedar a la deriva con su tripulación dentro; todavía puede ser reparada o remolcada. Consulta Rescates y Seguros antes de elegir cápsula o reclamación.']}]},
{id:'campana-kira',title:'Campaña de Kira Navarro',category:'Inicio',description:'Ocho encargos de bienvenida, protección de novato y el primer salto hacia Marte.',read:4,source:'Campaña visible · Novedades 0.9.50, 0.9.71 y 0.9.77',sections:[
{title:'Cómo empieza',paragraphs:['Kira Navarro es el enlace de pilotos de MSP en Meridian. La campaña arranca después de la introducción para una cuenta nueva. Consta de ocho misiones cortas alrededor de la Tierra y termina con el primer salto a Marte. Puedes saltar una misión o la campaña y retomarla desde el menú.','La recompensa anunciada para la campaña es 10.000 CR, la librea Promoción 2287 y una orientación de oficio. Esa cifra es la recompensa de campaña anunciada, no una promesa de 10.000 por misión.']},
{title:'Primer objetivo comprobado',paragraphs:['La primera misión pide despegar de Meridian y llegar a la baliza Lantern-1. Bajo el radar, el objetivo tiene un botón Ir que lleva la nave al destino. El mapa situó la baliza aproximadamente a 15 km de la estación; la distancia exacta depende de dónde esté tu nave.','La ventana de Kira se arrastra por la cabecera y vuelve a su posición original con doble clic. Pulsar el objetivo del HUD vuelve a abrir la explicación. Los pasos posteriores no se completaron en esta investigación, por lo que la wiki no inventa sus nombres ni recompensas individuales.']},
{title:'Protección de novato',paragraphs:['Las notas 0.9.50 anuncian protección frente a otros jugadores durante las primeras 5 horas de juego. Puede terminar antes si atacas a alguien o sales de la Tierra con la campaña completada. Los NPC pueden atacarte durante esa protección. La marca Novato aparece junto al nombre.','Recomendación: aprende combate, navegación y gestión de carga antes de viajar a zonas sin ley. La protección de novato no equivale a inmunidad frente a todos los peligros.']}]},
{id:'controles',title:'Controles y atajos',category:'Vuelo',description:'Los cuatro gestos básicos, las teclas del HUD y cómo personalizar el pilotaje.',read:4,source:'Menú → Ayuda · Vuelo observado · Novedades 0.9.22',sections:[
{title:'Cuatro gestos para jugar',paragraphs:['Clic izquierdo en el espacio vacío ordena movimiento. Clic izquierdo sobre una nave, estación u objeto lo selecciona. Clic derecho abre las opciones del objeto o del espacio. Arrastrar con el botón izquierdo gira la cámara y la rueda cambia el zoom.','El botón F activa la acción principal del objetivo: atracar, recoger o saltar según el contexto. El juego funciona con órdenes y clics; las teclas son atajos opcionales que puedes cambiar en Ajustes → Controles.'],bullets:['X: parar. Espacio: atacar o dejar de atacar. T: seleccionar el hostil más cercano.','M: mapa. L: lista de contactos. Intro: chat.','H: ayuda. P: perfil. K: enciclopedia.','F3: depuración. Esc: cerrar el panel actual o abrir el menú.']},
{title:'El menú no pausa la partida',paragraphs:['El menú de Esc avisa expresamente de que tu nave permanece en el espacio mientras lo consultas. Para leer con tranquilidad, atraca primero. Parar la nave con X no te hace inmune ni desconecta la simulación.']},
{title:'Mapa y minería',paragraphs:['En el mapa, arrastra para desplazar, usa el botón derecho o Mayús + izquierdo para girar y la rueda para el zoom. La tecla / enfoca el buscador. M o Esc cierran el mapa.','El rayo minero conserva cuatro ajustes con las teclas 1–4; Mayús permite guardarlos según las notas de 0.9.22. El último ajuste se conserva al reconectar.']}]},
{id:'navegacion',title:'SCM, NAV y viaje cuántico',category:'Vuelo',description:'Cómo viajar, conservar combustible y planificar saltos con paradas.',read:6,source:'Ayuda · Mapa · Novedades 0.6.4, 0.6.20, 0.7.83 y 0.9.50',sections:[
{title:'Dos modos de vuelo',paragraphs:['SCM es el modo de combate: funcionan armas y escudos, con una velocidad máxima menor. NAV permite viajar más deprisa, pero desactiva armas y escudos. La velocidad de crucero sostenida en SCM puede ser inferior a la máxima de combate, especialmente en las naves grandes.','Las fichas de nave conservan velocidad de combate, velocidad de crucero, aceleración, giro, masa y blindajes. Usa el comparador para decidir si prefieres velocidad, capacidad de carga o resistencia.']},
{title:'Cuántico y combustible',paragraphs:['QT permite viajar a un objeto situado a más de 10 km. El motor carga antes del salto y consume combustible cuántico. El hidrógeno y el combustible QT aparecen por separado en el HUD y en Servicios.','Las notas 0.6.4 indicaban unos 800 km de alcance con una Albor llena y unos 700 con un Halcón. Son referencias de esa actualización, no distancias garantizadas para todas las configuraciones: utiliza la predicción actual del mapa.']},
{title:'Ir y las paradas',paragraphs:['Ir planifica el movimiento al destino, rodea planetas y puede añadir paradas para repostar. La ruta muestra distancia, tiempo y combustible previsto. Las actualizaciones posteriores especifican que atraca, reposta y continúa; evita detenerse en la estación de salida.','Puedes preparar la ruta desde el hangar. Comprueba que el destino permite atracar, que tienes reputación suficiente y que las estaciones intermedias venden combustible. El Depósito Helios sirve como apoyo en el sistema interior.']},
{title:'Interdicción y emergencia',paragraphs:['Un interdictor puede sacar una nave del cuántico. Las rutinas e Ir esperan a que vuelva a ser posible saltar cuando corresponde. Un campo de interdicción bloquea el viaje dentro de su alcance.','Si te quedas sin combustible cuántico y no alcanzas ninguna estación, el menú ofrece un remolque de emergencia a la estación con combustible más cercana. Hay una tarifa; las notas indican que se usa lo que tengas si no alcanza. Otra opción es una baliza de socorro y rescate por un jugador.']}]},
{id:'mapa-radar',title:'Mapa, radar y sensores',category:'Vuelo',description:'Buscar destinos, leer la seguridad y filtrar contactos sin perderte entre marcadores.',read:6,source:'Mapa y HUD observados · Novedades 0.6.20 y 0.7.70',sections:[
{title:'Sistema, zona y local',paragraphs:['El mapa permite pasar del sistema completo a una zona o a tu entorno local. Su buscador consulta destinos en todo Sol y también mercancías a la venta, con hasta 12 resultados según 0.7.70. Seleccionar un elemento abre su ficha de mercado, contratos, historia y acceso.','Los filtros Mostrar separan estaciones, contratos, eventos, minería, peligro, pilotos y restos. Cerca de ti reduce el listado local y Guardadas muestra tus rutinas. Las capas incluyen zonas de ley, rutas comerciales, precios, actividad, alcance cuántico, contratos y minería.']},
{title:'El alcance lo determina el escáner',paragraphs:['Los rangos del radar son opciones de visualización dentro de la capacidad del componente montado. Elegir 100 km no aumenta un MSP Ojo de 12 km: los rangos fuera de alcance aparecen desactivados. Los sensores de serie suelen aumentar con el tamaño de nave, y las variantes Largas alcanzan más lejos.','Los contactos lejanos y los de sectores vecinos pueden aparecer dentro de tu alcance. Las balizas de socorro públicas también dependen del escáner. La ficha de cada componente recoge alcance y compatibilidad.']},
{title:'Perfiles de contactos',paragraphs:['Combate, Minería y Desguace activan grupos de filtros. En Minería puedes filtrar ferrita, corundita, aurelio e hielo y tamaños de roca: pequeña, menos de 3 SCU; mediana, de 3 a 6; grande, 7 SCU o más y láser S2.','El panel de contactos se abre con L. Elegir un contacto fija el objetivo. El Sabueso de la Gavilán incorpora identificación de CrimeStat según las notas de su presentación.']},
{title:'Leer seguridad',paragraphs:['La leyenda diferencia con ley, ley media y sin ley. La seguridad numérica de zona y su ley se muestran en el HUD. El mapa de esta wiki es un esquema de relaciones entre estaciones, no reproduce coordenadas, distancias ni actividad en tiempo real.']}]},
{id:'comercio',title:'Comercio y economía de estaciones',category:'Economía',description:'Precios, oferta, demanda, reputación y la diferencia entre beneficio bruto y neto.',read:7,source:'Mercado · Enciclopedia · Novedades 0.9.80, 0.7.71 y 0.9.22',sections:[
{title:'Comprar, vender, órdenes y precios',paragraphs:['El mercado tiene cuatro pestañas: Comprar, Vender, Órdenes y Precios. Los filtros permiten limitar mercancías por categoría y por beneficio. La tabla muestra coste local, destino que paga más, existencias y cantidad a bordo.','Lo necesita señala consumo por fábricas, tripulación o astillero. Le sobra indica producción superior al consumo. Una existencia baja puede encarecer un recurso, limitar compras y afectar la producción de naves. La enciclopedia conecta estos recursos con sus fábricas.']},
{title:'Un precio no es fijo',paragraphs:['Las cotizaciones cambian según existencias y reputación. Las fichas de materiales se capturaron durante la investigación del 10 de octubre de 2026. Las estaciones también muestran precios de referencia, que pueden diferir de la cotización del mercado en el mismo momento.','Desde 0.9.80, vender mucha carga de un recurso demandado puede bajar su precio incluso cuando estaba pagando su máximo. Las notas describen una recuperación en una hora. La cantidad total se valora con un precio medio real por SCU, no necesariamente con el primer precio de la tabla.']},
{title:'Calcular una operación',paragraphs:['Beneficio bruto = cantidad × (precio de venta − precio de compra). Beneficio neto = venta − compra − combustible − reparaciones − otras comisiones. En ventas de rutina hay una comisión del 1,25 % del importe vendido.','La calculadora de esta wiki usa los precios que introduzcas. Los ejemplos precargados son ilustrativos; no conectan con el mercado vivo. Introduce el precio medio real y los costes de la ruta antes de decidir.'],bullets:['Comprueba SCU libres después de reservar paquetes y componentes.','Mira la legalidad del recurso en el destino.','Verifica tu rango de reputación para comerciarlo.','Deja un margen de créditos para volver y reparar.','Compara el ingreso por hora, además del beneficio por viaje.']},
{title:'Órdenes y jugadores',paragraphs:['Órdenes es una función distinta de comprar mercancía inmediata. El menú ofrece Mis órdenes para gestionarlas. Esta investigación no colocó órdenes ni comprobó sus tarifas y plazos, por lo que no se atribuyen condiciones no observadas. Los contratos entre jugadores sí reservan el pago hasta que se cumplen, según las notas de Sociedad.']}]},
{id:'mineria',title:'Minería y calibración del haz',category:'Industria',description:'Rocas, resonancia, tamaños y progresión desde la Albor hasta la Cachalote.',read:7,source:'Radar · Equipamiento · Enciclopedia · Novedades 0.5.1, 0.7.52 y 0.9.22',sections:[
{title:'El equipo inicial',paragraphs:['La Albor de cortesía trae un MSP Pico montado en la partida observada. No confundas el hueco de utilidad vacío de la ficha genérica de catálogo con el equipamiento real de tu nave inicial. Las piezas de regalo no se pueden vender; al desmontarlas se desguazan.','Los láseres mineros tienen alcance, rendimiento y capacidades distintas. Un láser S2 es necesario para las rocas grandes. La compatibilidad se consulta por componente; comprar un cabezal sin un hueco adecuado no permite usarlo.']},
{title:'Encontrar recursos',paragraphs:['Pale Ring y Cantera de Cairn son fuentes de ferrita al 100 % en la enciclopedia. Cinder Field contiene ferrita al 45 %, corundita al 25 % y otros recursos que se detallan en sus fichas. Ember Veil incluye ferrita al 40 % y corundita al 40 %.','Los porcentajes describen la composición indicada por el catálogo; no son una garantía de ganancias ni de disponibilidad instantánea. Las fichas de cada mineral enlazan todas sus fuentes observadas.']},
{title:'Trabajar el haz',paragraphs:['La minería usa potencia, frecuencia y apertura. Cada mineral tiene una banda de resonancia y las rocas pesadas responden con retraso. Las notas 0.5.1 atribuyen un 10 % extra a una fractura limpia. Ajusta mirando la respuesta de la roca, en vez de mantener potencia máxima por defecto.','La nave se detiene antes de empezar a minar. Puedes guardar cuatro ajustes y conservar el último al reconectar. El panel permite apagar el rayo. La minería de rutina funciona más despacio que a mano.']},
{title:'Progresión de oficio',paragraphs:['La Gaviota es una opción de iniciación especializada; la Cormorán S2 combina 40 SCU y un puesto de minero; la Cachalote S4 tiene 180 SCU y tres haces de extracción. Estos datos se comparan en las fichas y en el comparador.','Recomendación: decide por bodega, láser y acceso al mercado, no solo por el rendimiento del cabezal. Una bodega pequeña obliga a volver con frecuencia. Un segundo minero permite repartir trabajo entre pilotaje y extracción.']},
{title:'Vender o refinar',paragraphs:['Puedes vender el mineral, entregarlo a un pedido o llevarlo a una refinería. Los pedidos de mineral volvieron a pagar por encima del mercado en 0.9.77. Calcula tiempo, carga, destino y requisito del contrato antes de elegir.']}]},
{id:'refinado',title:'Refinado y cadenas de materiales',category:'Industria',description:'Cómo convertir recursos brutos en suministros para fábricas y componentes.',read:5,source:'Ayuda · Enciclopedia · Novedades 0.5',sections:[
{title:'Materia prima y productos',paragraphs:['El mineral y la chatarra pueden refinarse en Cairn y Blackwake. La ferrita conduce a lingotes de ferrita, la corundita a cristal de corundita, el aurelio a lingotes de aurelio y la chatarra a aleación reciclada. Los recursos refinados alimentan planos, reparación y producción industrial.','La enciclopedia distingue el refinado que puedes encargar y la producción continua de las fábricas de la estación. Una tasa /h de una fundición de estación describe su economía; no es el tiempo de tu trabajo de refinado.']},
{title:'Método y rendimiento',paragraphs:['La ayuda indica que los métodos más lentos rinden más. Decide si priorizas liberar carga y cobrar pronto o sacar más producto del recurso. Esta investigación no recorrió la pantalla de refinado de Cairn y Blackwake, así que no se publican nombres, tarifas ni rendimientos de métodos que no se comprobaron.','En una rutina existe un paso Refinar y otro Recoger lo refinado o fabricado. Incluye la recogida en tu planificación: producir y disponer del producto son pasos diferentes.']},
{title:'Leer la cadena industrial',paragraphs:['Las fichas de material muestran de dónde sale, para qué sirve y dónde se comercia. Las fichas de estaciones conservan los insumos y salidas de sus fábricas. Por ejemplo, la fundición de ferrita de Cairn consume 240 por hora y produce 180 de lingotes por hora; son cifras de fábrica de estación.','Los recambios y metales refinados alimentan astilleros. Llevar suministros a una estación puede facilitar su fabricación de nuevos cascos. No confundir el coste de materiales del astillero con una lista de mercancías que el comprador deba entregar al comprar una nave.']}]},
{id:'fabricacion',title:'Planos y fabricación',category:'Industria',description:'Requisitos, ingredientes, tasas, colas y variantes que solo pueden fabricarse.',read:7,source:'Fabricación de Meridian · Enciclopedia · Novedades 0.9.25 y 0.9.81',sections:[
{title:'Aprender un plano',paragraphs:['Un plano desbloquea la receta; aprenderlo tiene un coste distinto de los materiales y de la tarifa de cada trabajo. La interfaz enseña nivel, reputación requerida, ingredientes, créditos y minutos. En Meridian se observaron hasta 3 trabajos de fabricación.','Material de reparación es de nivel 0: aprender cuesta 1.500 CR y producir 1 SCU usa 0,8 SCU de aleación reciclada, 0,4 de lingotes de ferrita, 60 CR y 5 minutos. Es un ejemplo comprobado, no una regla de coste universal.']},
{title:'Reputación y variantes',paragraphs:['Los planos de nivel 1 visibles en Meridian piden De confianza con MSP; los de nivel 2 suelen pedir Respetado, y los de nivel 3 Honrado. Algunos planos se ganan en una cadena de contratos y no se desbloquean pagando sin más.','MSP Muralla Rápida aparece como recompensa de la cadena MSP: tiene 3.900 de capacidad y 294 de recuperación por segundo tras 5 segundos sin impactos. MSP Granizo Frío se vincula a HCA y combina 248 DPS con 1.350 disparos. Son variantes con ventajas y renuncias, no mejoras en todos los atributos.']},
{title:'La industria de componentes grandes',paragraphs:['Desde 0.9.25, los componentes de fabricante S2 en adelante se obtienen mediante fabricación o jugadores, mientras los S1 y soportes permanecen en tiendas. Usa Dónde se compra y Se fabrica en de la ficha para identificar el acceso de cada pieza.','El precio de catálogo de un componente que no se vende hecho es una referencia de valoración. No implica existencias en una tienda. Componentes y planos pueden estar sujetos a rangos.']},
{title:'Encargos de fabricación',paragraphs:['Los contratos indican plano, origen, materiales, lugar de producción y plazo. El encargo observado de dos Hollow Espina requería entregar desde el almacén de Meridian en 24 horas; se fabricaban en Rust Hollow.','0.9.81 diferencia producción propia de componentes comprados: lo fabricado por ti remunera materiales y minutos sin el antiguo techo de catálogo; lo comprado mantiene su tratamiento previo. Las notas 0.8.25 indicaban que fabricar para un encargo ya aceptado no cobra la tarifa de fabricación. Comprueba el contrato actual antes de producir.']}]},
{id:'desguace',title:'Desguace, pecios y componentes usados',category:'Industria',description:'Recuperar chatarra, desmontar piezas enteras y llevarlas a un nuevo destino.',read:5,source:'Ayuda · Enciclopedia · Novedades 0.5, 0.6.22, 0.7.52 y 0.9.22',sections:[
{title:'Herramientas y restos',paragraphs:['Un cabezal de salvage Hollow Garra puede recuperar componentes enteros de un pecio. La chatarra recuperada se vende o se refina a aleación reciclada. Comprueba tamaños y compatibilidad: ciertos pecios de carguero de 4–6 SCU requieren una garra o láser S2 según 0.6.22.','El radar Desguace filtra pecios, chatarra y botín. Hay un filtro de restos con componente y marcadores que identifican si el objeto contiene una pieza recuperable. Los campos de restos citados por el planificador son Old Drydock, Sable Drift y The Boneyard.']},
{title:'Un componente también ocupa carga',paragraphs:['Los componentes sueltos viajan en la bodega. Puedes llevarlos a otra estación, guardarlos, venderlos o montarlos allí. Las pantallas de almacén separan mercancías de componentes, y las piezas tienen un volumen que hay que considerar.','Los campos de restos se rellenan en unos 20 minutos según 0.6.22. Es una referencia de actualización; no implica que siempre encuentres el mismo botín en cada visita.']},
{title:'Pecio y nave inutilizada',paragraphs:['Un pecio no es lo mismo que la nave inutilizada de un jugador. Donde hay ley, saquear, remolcar sin contrato o rematar la nave de otro puede ser delito. El juego presenta un aviso antes de esas acciones.','Las notas 0.7.31 ampliaron el saqueo a la bodega completa; una actualización anterior mencionaba la mitad. La regla más reciente prevalece. Las naves NPC inutilizadas se convierten en pecios después de 10 minutos según 0.7.30.']}]},
{id:'contratos',title:'Contratos y límites de ingresos',category:'Misiones',description:'Entregas, caza, pedidos, fabricación y trabajos entre pilotos.',read:8,source:'Tablón de Meridian · Novedades 0.9.75–0.9.81, 0.8.30 y 0.7.0',sections:[
{title:'Cómo leer un contrato',paragraphs:['El tablón separa Todos, Facción y Jugadores y permite filtrar tipos. Cada contrato muestra objetivo, volumen, recompensa, reputación y riesgo. El HUD tiene Ir para el objetivo seleccionado; con varios contratos, puedes elegir cuál seguir.','Durante la visita había una entrega de cadena a Cairn de 1 SCU por 2.500 CR y +3 MSP, y una caza de Raider Tallo cerca de Pale Ring por 11.500 CR y +5 HCA. Son ejemplos del tablón, no trabajos que siempre tendrán el mismo pago.']},
{title:'Entregas y fases',paragraphs:['Una entrega simple transporta el paquete indicado al destino. Las entregas por fases pueden incluir recogida y entrega en estaciones distintas y hasta 4 tramos. Cada tramo paga y completar la cadena añade un 25 % según 0.8.30. Si abandonas o vence un tramo, conservas lo ya cobrado.','Desde 0.9.76, las entregas tienen un techo anunciado de 45.000 CR por hora; el tablón informa de lo que queda al aceptar. La carga grande ya no implica crecer indefinidamente en ingresos de entregas.']},
{title:'Caza de piratas',paragraphs:['Desde 0.9.75 se anuncian 5 cobros por piloto cada 2 horas para caza por contrato. Lo ya aceptado puede entregarse. Las recompensas cuentan al inutilizar al objetivo, según 0.7.30; no necesitas rematarlo para que cuente el derribo.','Los piratas generados por algunos rescates no tienen recompensa. No confundas caza por contrato, recompensa espontánea por pirata y participación en un evento. El riesgo 3 puede exigir más equipo que una Albor inicial.']},
{title:'Mineral y fabricación',paragraphs:['Los pedidos requieren una cantidad específica y un lugar de entrega. La etiqueta Urgente modifica el incentivo y no convierte todos los contratos en una tarifa fija. 0.9.77 volvió a situar los pedidos de mineral por encima de la venta directa, corrigiendo 0.9.75.','Los encargos de fabricación requieren componente, almacén, plano y plazo; algunos trabajos son Compra de componente y admiten una pieza fabricada o adquirida. Lee el tipo exacto antes de gastar materiales.']},
{title:'Contratos entre jugadores',paragraphs:['Los tipos anunciados incluyen transporte con fianza, suministro pagado por SCU, escolta comprobada por el juego y recompensa por un piloto. La paga queda reservada hasta el cumplimiento. Consulta siempre la fianza y condiciones antes de aceptar.','Se pueden abandonar como máximo 3 contratos por cada 10 minutos según 0.9.75. No aceptes trabajos imposibles solo para sustituirlos repetidamente. La wiki no publicó contratos durante la investigación.']}]},
{id:'facciones',title:'Facciones y reputación',category:'Universo',description:'HCA, MSP, FMU, Nox y Tharsis: quién gobierna y qué desbloquea tu rango.',read:7,source:'Perfil · Fabricación · Novedades 0.5, 0.6.5, 0.6.9 y 0.7.60',sections:[
{title:'Las cinco facciones',paragraphs:['HCA, Autoridad Civil Heliocéntrica, representa la autoridad terrestre y administra la prisión de Cairn. MSP, Maxo Space Industries, fabrica la línea de naves civiles y tiene Meridian como sede de partida. FMU, Unión de Mineros Libres, se vincula a Ceres y su economía minera.','El Sindicato Nox opera desde Blackwake y los troyanos de Júpiter. La República de Tharsis controla la industria naval marciana y fabrica en Fobos. Tu reputación se mide por separado con cada facción.']},
{title:'Rangos comprobados',paragraphs:['El perfil inicial muestra Sospechoso a −10, Neutral a 0, Conocido a +10 y el próximo rango De confianza a +25. La interfaz también utiliza Respetado y Honrado, y las notas describen un recorrido de Enemigo a Honrado. No se asignan umbrales numéricos a los rangos que no se observaron.','Conocido con MSP, en la cuenta investigada, indica −5 % al comprar y +3 % al vender en sus estaciones. Otros rangos pueden modificar pagos, acceso y planos; comprueba el perfil y el requisito local.']},
{title:'Las cadenas importan',paragraphs:['Los contratos sueltos normalmente suben hasta De confianza. Para llegar a Respetado, las notas indican completar la cadena de la facción y consultar dónde se acepta. Una vez completada, contratos sueltos pueden recuperar reputación por encima de De confianza si después la pierdes.','En Meridian se observaron Los más buscados (HCA) y Logística de Meridian (MSP), ambas con paso 1/4. Guardia de Fobos (Tharsis) se anuncia como una cadena de cuatro trabajos que termina en un capitán de 55.000 CR. La investigación no completó esas cadenas.']},
{title:'Acceso y conflictos',paragraphs:['Una estación puede negar el atraque por mala reputación y avisa antes de llegar. Algunas mercancías restringidas exigen rango: las notas citan lingotes de aurelio en Cairn con Conocido FMU. La etiqueta restringido no equivale siempre a contrabando.','Cazar piratas dejó de costar reputación con otras facciones según 0.6.5. Los trabajos políticos de HCA o Tharsis pueden restar reputación al otro bando, con los límites descritos por la actualización.']}]},
{id:'combate',title:'Combate, energía y supervivencia',category:'Combate',description:'Armas, calor, escudos, munición y qué pasa cuando el casco llega a cero.',read:7,source:'Ayuda · Enciclopedia · Novedades 0.7.30, 0.7.31 y 0.9.0',sections:[
{title:'Elegir el arma',paragraphs:['Las fichas conservan daño, DPS y alcance. DPS es una referencia nominal del arma, no una garantía de daño real contra cualquier blanco. Los láseres consumen recursos de energía y generan calor; los balísticos tienen munición limitada. La cadencia, el alcance, el blindaje del objetivo y la refrigeración importan.','Un soporte de misil no es el misil mismo: verifica el tamaño de rack y munición compatible. La Albor inicial mostró 2 misiles y 8 señuelos en vuelo. Reposición y rearme se consultan en Servicios.']},
{title:'Escudo y planta',paragraphs:['Los escudos tienen capacidad, recuperación y demora tras recibir impactos. La planta proporciona puntos para repartir entre armas, escudos y motores; la Albor comienza equilibrada en 2/2/2. Las IA de torreta también reservan energía.','Recomendación: compara la resistencia de escudo y la recuperación con el ritmo del combate que haces. Una variante de regeneración puede tener menos capacidad total. Cambiar una planta o un refrigerador no aumenta automáticamente el daño de todas las armas.']},
{title:'Torretas',paragraphs:['Las torretas giran e inclinan dentro de un arco y a una velocidad propia. Fuera del arco se detienen y no disparan. Hace falta un artillero o un asistente IA montado y disponible. El piloto no debe suponer que todas las armas de una nave grande están trabajando.']},
{title:'Casco a cero',paragraphs:['0.7.30 cambió el final del combate: al vaciar el casco, la nave queda inutilizada, sin motores, armas ni escudo y con la tripulación dentro. Rematarla requiere daño adicional equivalente a otra mitad de casco. La nave puede persistir aunque su dueño se desconecte.','Las piezas ya no se desprenden como antes durante el combate. El daño visual muestra humo, chispas y fuego. El fuego por sí solo no inutiliza: en cascos de un asiento se apaga automáticamente a los 8 segundos; en naves con ingeniería, sin ingeniero, deja de extenderse y se apaga a los 30.']},
{title:'Colisiones y armisticio',paragraphs:['El escudo de proximidad evita daño por colisión con estaciones, rocas, planetas y otras naves, según 0.7.2. No es el escudo de combate de tus generadores. Dentro del armisticio de Meridian, el HUD indica armas apagadas.']}]},
{id:'ley-crimen',title:'CrimeStat, policía y prisión',category:'Combate',description:'La escala de antecedentes, las zonas sin patrulla y la legalidad de tus acciones.',read:5,source:'Ayuda · Novedades 0.7.30, 0.7.31 y 0.7.40',sections:[
{title:'Escala de CrimeStat',paragraphs:['CrimeStat va de 0 a 5. La ayuda describe 1 como una multa pagable en estación, 2 como intervención hostil de la policía y 3 o más como recompensa por tu cabeza. Baja un punto cada 20 minutos sin cometer delitos.','La ley de una zona y la presencia de patrulla son cosas relacionadas pero diferentes. En el Cinturón, el espacio joviano y el espacio abierto, los delitos pueden subir CrimeStat aunque la policía no acuda, según 0.7.31.']},
{title:'Acciones que importan',paragraphs:['Remolcar la nave de otro sin un rescate, saquearla o rematarla pueden ser delitos donde hay ley. La interdicción de área de la Hellas añade +2 de CrimeStat al activarse en zonas con ley y no puede encenderse dentro del armisticio.','Un contrato de rescate NPC autoriza a su titular a remolcar la nave y no cuenta como delito. Las guerras de organizaciones tienen condiciones especiales de seguridad, explicadas en la guía de organizaciones.']},
{title:'Ser capturado',paragraphs:['Si quedas inutilizado con un CrimeStat que conduce a prisión en zona donde opera la ley, la policía puede rematar la nave y enviarte a Cairn. La cápsula o desconectar no garantizan escapar de esa consecuencia.','La investigación no cumplió una condena ni recorrió el panel de prisión. Por ello no se publican duraciones de condena, tarifas de salida o métodos de reducción que no se hayan comprobado.']}]},
{id:'seguros',title:'Seguros, hogar y pérdida de naves',category:'Servicios',description:'Qué cubre cada póliza, cuánto dura y por qué tu carga no vuelve.',read:5,source:'Servicios de Meridian · Notas de la estación',sections:[
{title:'Básica y Completa',paragraphs:['Básica recupera el casco con su equipo de serie. Completa recupera el equipo montado hasta los límites cubiertos. Ambas duran 14 días; renovar añade 14 días a su vencimiento. Una reclamación consume la póliza.','En la Albor inicial se observaron 5.700 CR para Básica y 6.600 para Completa. Son los importes de esa nave en esa pantalla; no se extrapolan a todos los modelos.']},
{title:'La reclamación',paragraphs:['La nave asegurada vuelve reparada y con combustible, pero sin carga. Reclamar no tiene coste directo según Servicios, aunque consume la póliza. La cobertura de equipo depende de la modalidad y límites; consulta la interfaz antes de asumir que una mejora cara está cubierta.','Una nave destruida sin póliza vigente se pierde para siempre con lo que transportaba. La inutilización no equivale todavía a destrucción: considera reparación y remolque antes de reclamarla como perdida.']},
{title:'Hogar y cortesía',paragraphs:['La estación hogar es donde reapareces. La cuenta de investigación tiene Meridian como hogar y los servicios lo indican. En casa hay una Albor de cortesía gratuita si te quedas sin nave.','Recomendación: reserva el seguro para el casco y mejoras que no puedes reemplazar cómodamente. La póliza no protege el inventario de bodega; el volumen y valor transportado siguen siendo un riesgo separado.']}]},
{id:'rescates',title:'Rescates y remolque',category:'Servicios',description:'Balizas, Grulla, Camello y los requisitos reales de cada rescate.',read:8,source:'Contratos · Enciclopedia · Novedades 0.7.30, 0.7.40, 0.7.50 y 0.7.60',sections:[
{title:'Leer el requisito antes de aceptar',paragraphs:['Los rescates NPC pueden pedir remolcar o repostar en el sitio. El tablón muestra tamaño, distancia y equipo requerido, y avisa si tu nave no puede realizarlo. La nave varada aparece al aceptar; solo el titular del contrato puede remolcarla como parte de ese rescate.','El tablón observado incluía una Yunque S2 que requería una nave de rescate con pilas o un tractor S2 o mayor. Una Albor vacía de equipo apropiado no puede completar cualquier rescate solo por tener espacio en bodega.']},
{title:'Grulla: remolque y reparación',paragraphs:['El Cabestrante de la Grulla engancha desde 200 m y permite remolcar hasta S3 con una sola Grulla; una S4 necesita dos. Las notas describen una velocidad de remolque superior a la de un tractor normal. Un operador puede enganchar y soltar mientras el piloto navega.','La reparación de emergencia a menos de 100 m devuelve el 15 % de casco de una nave inutilizada en 3 minutos, o 1,5 con operador, consumiendo material de reparación. Un ataque a cualquiera de las dos interrumpe el proceso.']},
{title:'Repostaje y enfermería',paragraphs:['La Grulla reposta con pilas de combustible cuando ambas naves están casi detenidas y a menos de 100 m. Cada SCU proporciona hasta 75 % de hidrógeno y 37,5 % de cuántico, y solo se gasta la parte necesaria. Su enfermería tiene 4 plazas.','La Camello es una nave cisterna: puede ofrecer hidrógeno y combustible QT a otros pilotos con una manguera y precio acordado en el juego. También cumple rescates NPC de repostaje. No funciona igual que pasar pilas desde la Grulla.']},
{title:'Balizas y peligro',paragraphs:['Las balizas de socorro ofrecen una recompensa que se paga al cumplir el rescate. Las de organización y aliados se muestran de inmediato; las públicas llegan antes a una Grulla y tras 2 minutos al resto según 0.7.40. La Grulla recibe un 20 % extra de paga de rescate anunciado.','Los rescates de riesgo 3 pueden generar piratas: las notas citan dos Raider al enganchar o un saqueador tras 10 minutos sin acudir. Esos piratas no tienen recompensa. Planifica defensa y ruta de regreso.']}]},
{id:'tripulacion-ia',title:'Tripulación, ingeniería y asistentes IA',category:'Naves',description:'Qué hace cada puesto y por qué una nave multitripulada no dispara todas sus torretas sola.',read:6,source:'Enciclopedia · Novedades 0.3, 0.7.40, 0.9.20 y 0.9.30',sections:[
{title:'Cada asiento tiene un trabajo',paragraphs:['El piloto mueve la nave. Los artilleros controlan torretas; los mineros pueden controlar cabezales; el operador gestiona funciones de rescate o interdicción. El ingeniero reparte energía, apaga fuegos, repara en vuelo y rearma fusibles según la presentación de Tripulación.','La ficha conserva la tripulación de cada casco y sus huecos de equipo. Algunas S4 incorporan comandante y hasta un tercer artillero. No todos los puestos están presentes en todas las naves.']},
{title:'Asistentes de torreta',paragraphs:['Las naves con artillero tienen un hueco IA por puesto. Hollow Perro y MSP Escudero S1 actúan al 50 % de la referencia de artillero; Tharsis Centurión S2, al 60 % según 0.9.20. Su puntería y reacción son inferiores a las de una persona.','El asistente sigue el objetivo del piloto o, si no lo hay, a quien atacó en los últimos 30 segundos. Un jugador que ocupa el puesto deja la IA en espera. La IA no reemplaza automáticamente a todos los tripulantes de la nave.']},
{title:'Energía y límites',paragraphs:['El Escudero visible en Fabricación tiene 1,5 s de reacción y reserva 1 punto de energía. Consulta la ficha de cada asistente para su consumo y prestaciones; no presupongas los mismos datos en Perro y Centurión.','Recomendación: comprueba arcos de torreta y planta disponible antes de elegir una nave para jugar solo. Añadir una IA exige componente, hueco compatible y energía, además de reputación o fabricación cuando corresponda.']},
{title:'Comandante',paragraphs:['El comandante de S4 puede marcar un objetivo principal para artilleros e IA, puntos de reunión y apoyo de organización. La vista táctica muestra casco y escudo de flota; los demás pilotos pueden seguir al comandante.']}]},
{id:'rutinas',title:'Rutinas y automatización integrada',category:'Economía',description:'Planificar un ciclo, estimar costes y elegir cómo responder al peligro.',read:7,source:'Mapa → Rutinas · Novedades 0.6.20, 0.7.41, 0.7.29 y 0.9.21',sections:[
{title:'Plantillas y guardado',paragraphs:['Las cinco plantillas observadas son Minar y vender, Ruta comercial, Refinar y vender, Entregas y Desguace y venta. Puedes guardar hasta 10 rutinas, compartir un código SIS-R1-… e importar el de otro piloto. La importación muestra la ruta antes de guardarla.','Las repeticiones se definen por número de vueltas, horas o hasta que la pares. Ante peligro puedes Huir, Pausar y avisar o Seguir. La vista previa estima tiempo por vuelta, ventas, comisión, combustible y neto.']},
{title:'Pasos disponibles',paragraphs:['El editor incluye Ir a, Minar, Vender, Comprar, Descargar al almacén, Cargar del almacén, Refinar, Recoger lo refinado o fabricado, Fabricar, Repostar, Reparar, Aceptar entrega, Entregar, Recoger restos y Esperar.','La plantilla Minar y vender mostraba Pale Ring → minar ferrita hasta llenar → Meridian → vender ferrita. La cifra de ingreso que mostraba era una estimación con el precio, nave y configuración de ese momento, no un rendimiento garantizado.']},
{title:'Coste y velocidad',paragraphs:['Las ventas automáticas descuentan el 1,25 % del importe de venta. Los pasos de compra o venta tardan como máximo 2 minutos según 0.7.41, corrigiendo tiempos más largos de 0.7.27. La minería y el desguace automáticos son más lentos que hacerlos a mano.','Las rutinas usan tus créditos para repostar y reparar. El beneficio bruto no recoge esos gastos; revisa el neto de la vista previa y tu saldo para varias vueltas.']},
{title:'Cuándo se detienen',paragraphs:['Una compra o venta restringida por rango impide empezar o pausa la rutina. Perder el rango durante el ciclo también puede detenerla. La destrucción de tu nave para la rutina y no lanza automáticamente la nave reclamada al seguro.','El panel en marcha ofrece Pausar, Parar y Tomar el control. Un clic de movimiento mientras trabaja pide confirmación. Esta guía se refiere exclusivamente a las rutinas integradas del juego.']}]},
{id:'organizaciones',title:'Organizaciones, alianzas y guerras',category:'Comunidad',description:'Fundación, recursos compartidos, permisos y condiciones de guerra.',read:6,source:'Organización · Novedades 0.7.0, 0.7.24 y 0.7.25',sections:[
{title:'Fundar o buscar',paragraphs:['Fundar cuesta 250.000 CR y requiere Conocido con alguna facción. El nombre debe tener 3–32 caracteres y la etiqueta 2–5 letras o cifras; ambos deben ser únicos. El buscador filtra por idioma, actividad y reclutamiento.','La investigación recorrió el directorio pero no fundó ni se unió a una organización. Los miembros y organizaciones cambian con el tiempo, por lo que no se presenta un ranking estático de jugadores como dato permanente.']},
{title:'Economía compartida',paragraphs:['Las organizaciones tienen rangos con permisos, banco común con tasa opcional, hangar, almacén y canales de chat. Aportar y retirar son acciones diferentes: un rango puede permitir una y limitar la otra. Puedes aportar desde la bodega al estar atracado.','Etiqueta y emblema se muestran en el casco. El mensaje del día admite hasta 500 caracteres y 10 líneas, sin enlaces; puede editarlo quien tenga el permiso, y solo lo ven miembros.']},
{title:'Alianzas y guerras',paragraphs:['La guerra se anuncia con 24 horas de antelación y dura una semana según 0.7.0. Atacar a enemigos de guerra no produce CrimeStat cuando la seguridad es menor de 0,8, y los derribos cuentan en un marcador. Fuera de esa condición no se debe asumir ausencia de consecuencias.','La coordinación de flota utiliza objetivos de comandante, reuniones y canales de organización. La wiki no ofrece acciones que envíen solicitudes, mensajes o declaraciones al juego.']}]},
{id:'flota-eventos',title:'Eventos de flota y convoyes',category:'Misiones',description:'Leviatán Nox, escoltas, reparto de recompensas y mando de S4.',read:5,source:'Novedades 0.9.30 · Herald y HUD',sections:[
{title:'Los eventos grandes',paragraphs:['0.9.30 anuncia dos eventos de flota diarios y avisos con una hora de antelación. Uno es la incursión del Leviatán del Sindicato, una capital pirata con 8–12 escoltas. Otro es el convoy pesado, que puede escoltarse con paga de HCA o Tharsis o asaltarse.','La seguridad puede bajar durante el evento; el HUD muestra esa modificación. El horario exacto no se comprobó en esta investigación y no se inventan horas fijas. Consulta los anuncios actuales del juego.']},
{title:'Participación y recompensa',paragraphs:['La bolsa se reparte por aportación: daño, tiempo, reparación y apoyo del comandante. Los tres mayores contribuyentes contra el Leviatán reciben un plano raro, según las notas. No se promete una cantidad fija a todos los participantes.','Mapa, chat, Herald e insignia del HUD muestran los eventos y la parte de recompensa. Los avisos del navegador son opcionales en Ajustes → Interfaz.']},
{title:'Elegir una función',paragraphs:['Recomendación: aporta de acuerdo con tu casco y equipo. Una nave de soporte puede ser útil reparando; una torreta requiere tripulación o IA; una carguera no se convierte en escolta por tener una bodega grande. Mantén una ruta de salida y comprueba el seguro.']}]},
{id:'astillero',title:'Astillero, compra y gestión de flota',category:'Naves',description:'Tamaños S1–S4, usados, traslado, abastecimiento y costes de reemplazo.',read:6,source:'Astillero · Enciclopedia · Novedades 0.9.78, 0.7.40 y 0.6.8',sections:[
{title:'Tres pestañas',paragraphs:['El astillero actual separa Tus naves, Naves a la venta y Naves usadas, con filtros por tamaño y función. La tarjeta de una nave muestra ubicación, estado, equipamiento y controles. Una gota permite activar repostaje automático al atracar según 0.9.78.','S1–S4 son clases de tamaño del casco. Un tamaño mayor suele ampliar funciones y capacidad, pero no es una mejora universal de velocidad, precio o manejo. Compara bodega, casco, crucero, aceleración, giro y tripulación.']},
{title:'Compra y suministro',paragraphs:['Cada estación tiene un catálogo propio y los precios de nave pueden variar por estación. Las fichas conservan dónde se compra y cuánto cuesta allí. Los astilleros consumen recambios y metales refinados al producir cascos; la falta de insumos puede agotar existencias.','Las S4 se fabrican por encargo con 24 horas de espera y hasta 2 en cola, según 0.7.40. Atracan en cunas grandes o se anclan fuera de estaciones que no las tienen; Rust Hollow se cita como ejemplo de anclaje a 2,8 km.']},
{title:'Trasladar una nave',paragraphs:['Mis naves y almacenes, accesible desde Perfil o menú, reúne tus cascos, su ubicación, bodega y almacenes por estación. Traer aquí permite trasladar una nave guardada en otro lugar.','Las notas 0.6.8 limitan el traslado al 8 % del valor del casco, o 12 % si el trayecto incluye una estación sin ley, con un máximo de 10 minutos. Son las condiciones publicadas por esa actualización; lee el coste actual antes de confirmar.']},
{title:'Usados y reventa',paragraphs:['Vender el casco devuelve una parte del valor, no el precio completo. Las notas 0.5 anunciaban 60 % del precio más la mitad del valor de mejoras. El importe real de la tarjeta incorpora el contexto de la nave; no lo sustituye la calculadora de comercio.','Las piezas de serie de la Albor de regalo se desguazan al desmontarlas. Conserva ese detalle antes de intentar venderlas o guardarlas para financiar otra nave.']}]},
{id:'almacenes-correo',title:'Almacenes, correo y comunicación',category:'Comunidad',description:'Transportar componentes, transferir cantidades y usar el buzón con adjuntos.',read:5,source:'Almacén · Novedades 0.7.0, 0.7.52 y 0.9.22',sections:[
{title:'Bodega y almacén',paragraphs:['La bodega viaja con la nave; el almacén pertenece a una estación concreta. Mis naves y almacenes resume lo guardado en cada lugar. Puedes transferir mercancías por cantidad, con opciones de 1, 10, máximo o un valor escrito.','Los componentes sueltos ocupan bodega y pueden montarse después en otra estación. Un encargo de fabricación puede pedir entrega desde el almacén del destino, aunque ya lleves las piezas a bordo.']},
{title:'Correo y adjuntos',paragraphs:['El correo permite adjuntar créditos y objetos del almacén, recogerlos en una estación y establecer pago contra entrega. Los avisos de contratos, guerras, multas y destrucción también aparecen en el buzón.','Recomendación: verifica destinatario, objeto y pago contra entrega antes de enviar o recoger. La investigación no envió mensajes ni objetos a otros pilotos.']},
{title:'Chat y Herald',paragraphs:['Clic derecho sobre un piloto permite abrir una conversación privada. Las notas de Sociedad describen 30 días de historial, entrega al conectar, bloqueo y denuncia. Los objetos pueden compartirse como enlaces de ficha dentro del chat.','Avisos guarda mensajes del servidor sobre compras, ventas y minería. The Sol Herald reúne cambios de versión, escasez, abundancia, guerras, organizaciones y resultados de convoyes e incursiones. Su portada es información del momento.']}]},
{id:'accesibilidad',title:'Ajustes y accesibilidad',category:'Inicio',description:'Contraste, daltonismo, HUD, sonido y rendimiento gráfico.',read:4,source:'Novedades 0.9.60, 0.9.75, 0.6.12 y 0.6.6',sections:[
{title:'Interfaz y legibilidad',paragraphs:['Ajustes → Interfaz incluye alto contraste, paletas para deuteranopía, protanopía y tritanopía, y subtítulos de avisos sonoros. La interfaz utiliza iconos y formas además del color y permite navegación de teclado con foco visible.','Los cuadros del HUD se desbloquean con su candado para moverlos y ajustar tamaño entre 70 % y 200 %. Restablecer posiciones recupera también los tamaños. La ventana de Kira se puede mover por separado.']},
{title:'Gráficos y sonido',paragraphs:['Brillo del cielo, Fondo liso, intensidad de resplandor y reducción de destellos ayudan a ajustar visibilidad. La resolución 3D puede bajar en equipos modestos y el juego elige una calidad inicial.','Música tiene su interruptor en Sonido. Las notas distinguen música contextual y temas de viaje; una actualización posterior retiró la música de fondo generada, por lo que no todas las pistas históricas siguen activas del mismo modo.']},
{title:'Si no inicia',paragraphs:['El juego utiliza aceleración gráfica del navegador. Las versiones recientes muestran instrucciones si no está disponible y un botón para recargar tras pérdida de la tarjeta gráfica. El estado del servidor está en sistoma.com/status.','Esta wiki es una instantánea de documentación, con búsqueda y herramientas locales. No necesita ejecutar el motor 3D ni iniciar sesión en Sistoma para consultar sus fichas.']}]},
{id:'normas-fuentes',title:'Fuentes, alcance y normas',category:'Wiki',description:'De dónde salen los datos y qué partes aún requieren comprobación.',read:4,source:'Investigación directa · Normas públicas · 10 de octubre de 2026',sections:[
{title:'Documentación comprobada',paragraphs:['La wiki se elaboró entrando con una cuenta de investigación autorizada, recorriendo los nueve menús de Meridian, Perfil, Ayuda, mapa, rutinas, HUD y Novedades. Se documentaron las 130 entradas del índice completo de la enciclopedia: 25 naves, 6 estaciones, 16 materiales y 83 componentes.','Las cifras de catálogo y relaciones industriales proceden de pantallas del juego. Las explicaciones de esta wiki son síntesis propias. Las recomendaciones se identifican como tales y las notas históricas se cruzan con las versiones más recientes observadas.']},
{title:'Fecha y límites',paragraphs:['Última versión visible: 0.9.82. Fecha de revisión: 10 de octubre de 2026. Las fichas no son datos en directo. Precios, existencias, horarios, contratos y balance pueden cambiar.','No se completaron todas las campañas, no se compraron naves avanzadas, no se recorrió prisión ni cada pantalla exclusiva de estaciones remotas. No se publican nombres de pasos, umbrales de reputación o tarifas de esos paneles sin evidencia. El catálogo de esas estaciones sí está documentado a través de la enciclopedia.']},
{title:'Normas de la comunidad',paragraphs:['La página pública de normas consultada se identifica como borrador pendiente de aprobación. En ella se describe una cuenta simultánea por persona, prohibición de trampas y herramientas externas que jueguen por ti, comercio por dinero real y conductas de acoso. Consulta el texto oficial vigente para sus condiciones completas.','La piratería y el contrabando dentro del juego forman parte de sus mecánicas; el respeto a otras personas y las normas del servicio son una cuestión distinta. Esta wiki documenta el juego y no tiene funciones para enviar acciones a tu cuenta.']}]}
];

