export const glossary=[['SCU','Unidad estándar de carga; la Albor tiene 3 SCU.'],['SCM','Modo de combate con armas y escudos disponibles.'],['NAV','Modo de viaje rápido, con armas y escudos apagados.'],['QT','Viaje cuántico a un destino a más de 10 km.'],['DPS','Daño nominal por segundo de un arma.'],['CrimeStat','Antecedentes del piloto, de 0 a 5.'],['Cardán','Montaje de arma articulado; consulta el hueco del casco.'],['Armisticio','Zona de protección de estación con armas desactivadas.'],['Pecio','Resto de una nave del que se recupera chatarra o componentes.'],['Inutilizada','Nave sin casco operativo que aún puede repararse o remolcarse.'],['Plano','Receta aprendida para fabricar un objeto.'],['Reputación','Relación individual con cada facción; desbloquea acceso y ventajas.']];
